package com.ecole.gestion_scolaire.hr.service; import com.ecole.gestion_scolaire.hr.dto.*; import com.ecole.gestion_scolaire.hr.enums.*; import com.ecole.gestion_scolaire.hr.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; import java.util.stream.*; @Service public class HrDashboardService { private final EmployeeRepository employees; private final TeacherRepository teachers; private final TeacherSubjectRepository subjects; private final TeachingAssignmentRepository assignments; private final CompensationPlanRepository plans; public HrDashboardService(EmployeeRepository e,TeacherRepository t,TeacherSubjectRepository s,TeachingAssignmentRepository a,CompensationPlanRepository p){employees=e;teachers=t;subjects=s;assignments=a;plans=p;} @Transactional(readOnly=true) public HrDashboardResponse dashboard(Long schoolYearId){var ts=teachers.findAllByOrderByEmployeePersonLastNameAscEmployeePersonFirstNameAsc();long active=ts.stream().filter(t->t.getStatus()==TeacherStatus.ACTIVE).count(), leave=ts.stream().filter(t->t.getStatus()==TeacherStatus.ON_LEAVE).count(), susp=ts.stream().filter(t->t.getStatus()==TeacherStatus.SUSPENDED).count();long noSub=ts.stream().filter(t->subjects.findByTeacherId(t.getId()).isEmpty()).count();long noAss=ts.stream().filter(t->assignments.findByTeacherIdOrderByStartDateDesc(t.getId()).stream().noneMatch(a->a.getStatus()==AssignmentStatus.ACTIVE&&(schoolYearId==null||a.getSchoolYear().getId().equals(schoolYearId)))).count();Map<String,Long> byCampus=employees.findAll().stream().collect(Collectors.groupingBy(e->e.getCampus()==null?"Sans campus":e.getCampus().getName(),LinkedHashMap::new,Collectors.counting()));Map<String,Long> bySubject=subjects.findAll().stream().collect(Collectors.groupingBy(x->x.getSubject().getName(),LinkedHashMap::new,Collectors.counting()));Map<String,Long> byComp=new LinkedHashMap<>();for(var e:employees.findAll()){var ps=plans.findByEmployeeIdOrderByEffectiveFromDesc(e.getId());String k=ps.isEmpty()?"NON_CONFIGURE":ps.get(0).getCompensationType().name();byComp.merge(k,1L,Long::sum);}var workloads=ts.stream().map(t->{var aa=assignments.findByTeacherIdOrderByStartDateDesc(t.getId()).stream().filter(a->a.getStatus()==AssignmentStatus.ACTIVE&&(schoolYearId==null||a.getSchoolYear().getId().equals(schoolYearId))).toList();var p=t.getEmployee().getPerson();return new HrDashboardResponse.TeacherWorkload(t.getId(),p.getFirstName()+" "+p.getLastName(),aa.size(),aa.stream().map(a->a.getSubject().getId()).distinct().count(),aa.stream().map(a->a.getClassGroup().getId()).distinct().count());}).toList();return new HrDashboardResponse(employees.count(),ts.size(),active,leave,susp,noSub,noAss,byCampus,bySubject,byComp,workloads);} }